class StandardMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def opening_action(self, game, grid, rows, cols):
        best = None
        best_dist = -1
        cr, cc = rows / 2.0, cols / 2.0
        for r in range(rows):
            for c in range(cols):
                dist = -((r - cr) ** 2 + (c - cc) ** 2)
                if best is None or dist > best_dist:
                    best_dist = dist
                    best = (r, c)
        return ("reveal", best[0], best[1])

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0
        p = prob_map.get(pos, 0.5)
        edge_penalty = 0.0
        if r == 0 or r == rows - 1 or c == 0 or c == cols - 1:
            edge_penalty = 0.04
        elif r == 1 or r == rows - 2 or c == 1 or c == cols - 2:
            edge_penalty = 0.02
        constrained_neighbors = sum(
            1 for nr, nc in neighbors_of.get(pos, [])
            if grid[nr][nc].is_revealed and grid[nr][nc].adjacent_mines > 0
        )
        constraint_bonus = -0.01 * constrained_neighbors
        adjusted = p + edge_penalty + constraint_bonus
        return (adjusted, -constrained_neighbors, self._rng.random())

class ParityConstraintMinesweeperAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def clue_value(self, game, grid, r, c):
        cell = grid[r][c]
        if not cell.is_revealed or cell.is_mine:
            return None
        return cell.adjacent_mines

    def postprocess_prob_map(self, game, grid, prob_map, mine_set, neighbors_of):
        rows = len(grid)
        cols = len(grid[0]) if rows > 0 else 0

        parity_constraints = []
        for r in range(rows):
            for c in range(cols):
                cell = grid[r][c]
                if not cell.is_revealed or cell.is_mine:
                    continue
                true_count = cell.adjacent_mines
                parity = true_count % 2
                nbrs = neighbors_of.get((r, c), [])
                flagged_count = sum(1 for nr, nc in nbrs if grid[nr][nc].is_flagged)
                known_mine_count = sum(1 for nr, nc in nbrs if (nr, nc) in mine_set and not grid[nr][nc].is_flagged)
                unknown_nbrs = [
                    (nr, nc) for nr, nc in nbrs
                    if not grid[nr][nc].is_revealed
                    and not grid[nr][nc].is_flagged
                    and (nr, nc) not in mine_set
                ]
                if not unknown_nbrs:
                    continue
                fixed_mines = flagged_count + known_mine_count
                effective_parity = (parity - fixed_mines) % 2
                parity_constraints.append((unknown_nbrs, effective_parity))

        for unknown_nbrs, effective_parity in parity_constraints:
            if len(unknown_nbrs) == 1:
                pos = unknown_nbrs[0]
                if effective_parity == 1:
                    if prob_map.get(pos, 0.5) < 0.85:
                        prob_map[pos] = max(prob_map.get(pos, 0.5), 0.85)
                else:
                    if prob_map.get(pos, 0.5) > 0.15:
                        prob_map[pos] = min(prob_map.get(pos, 0.5), 0.15)

        for unknown_nbrs, effective_parity in parity_constraints:
            if len(unknown_nbrs) == 2:
                p0 = unknown_nbrs[0]
                p1 = unknown_nbrs[1]
                prob0 = prob_map.get(p0, 0.5)
                prob1 = prob_map.get(p1, 0.5)
                if effective_parity == 1:
                    if prob0 < 0.1:
                        prob_map[p1] = max(prob_map.get(p1, 0.5), 0.8)
                    elif prob0 > 0.9:
                        prob_map[p1] = min(prob_map.get(p1, 0.5), 0.2)
                    if prob1 < 0.1:
                        prob_map[p0] = max(prob_map.get(p0, 0.5), 0.8)
                    elif prob1 > 0.9:
                        prob_map[p0] = min(prob_map.get(p0, 0.5), 0.2)
                else:
                    if prob0 < 0.1:
                        prob_map[p1] = min(prob_map.get(p1, 0.5), 0.2)
                    elif prob0 > 0.9:
                        prob_map[p1] = max(prob_map.get(p1, 0.5), 0.8)
                    if prob1 < 0.1:
                        prob_map[p0] = min(prob_map.get(p0, 0.5), 0.2)
                    elif prob1 > 0.9:
                        prob_map[p0] = max(prob_map.get(p0, 0.5), 0.8)

        return prob_map

class DriftingMinesFlagFirstAgent(ArchiveAwarePAFGAgent):
    def __init__(self, seed=None):
        super().__init__(seed=seed)

    def action_priority(self, game, grid, rows, cols):
        return "flag-first"

    def frontier_cell_score(self, game, grid, pos, prob_map, mine_set, neighbors_of):
        r, c = pos
        p = prob_map.get(pos, 0.5)
        flagged_neighbors = sum(
            1
            for nr, nc in neighbors_of.get((r, c), [])
            if grid[nr][nc].is_flagged
        )
        stabilized_bonus = -0.05 * flagged_neighbors
        return (p + stabilized_bonus, -flagged_neighbors, self._rng.random())
